// Extract the first article and build URL for 深談總經
const articles = $input.first().json.data.clientGetArticleList.filtered;

if (!articles || articles.length === 0) {
  throw new Error('No articles found for 深談總經');
}

const article = articles[0];

function sanitizeTitle(title) {
  return title
    .replace(/[^\u4e00-\u9fff\u3400-\u4dbfa-zA-Z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

const sanitizedTitle = sanitizeTitle(article.title);
const url = `https://www.sinotrade.com.tw/richclub/MacroExpert/${sanitizedTitle}--${article._id}`;

return {
  json: {
    articleId: article._id,
    title: article.title,
    viewCount: article.media.totalView,
    url: url,
    channel: '深談總經',
    targetCount: 200
  }
};

// Extract articles and filter for 川普專題
const articles = $input.first().json.data.clientGetArticleList.filtered;

if (!articles || articles.length === 0) {
  throw new Error('No articles found for 川普專題');
}

// Filter for articles with 【川普政策整理】 in title
const trumpArticles = articles.filter(a => a.title.includes('【川普政策整理】'));

if (trumpArticles.length === 0) {
  throw new Error('No 川普專題 articles found with title filter');
}

const article = trumpArticles[0];

function sanitizeTitle(title) {
  return title
    .replace(/[^\u4e00-\u9fff\u3400-\u4dbfa-zA-Z0-9]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

const sanitizedTitle = sanitizeTitle(article.title);
const url = `https://www.sinotrade.com.tw/richclub/hotstock/${sanitizedTitle}--${article._id}`;

return {
  json: {
    articleId: article._id,
    title: article.title,
    viewCount: article.media.totalView,
    url: url,
    channel: '川普專題',
    targetCount: 2000
  }
};

// Build notification message
let macroResult = $('Boost View 深談總經').first().json
let trumpResult = $('Boost View 川普專題').first().json

const now = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

return {
  json: {
    macroResult: {
      totalToRun: macroResult.totalToRun.toLocaleString(),
      successCount: macroResult.successCount.toLocaleString(),
      failCount: macroResult.failCount.toLocaleString(),
      oldViewCount: macroResult.oldViewCount.toLocaleString(),
      newViewCount: macroResult.newViewCount.toLocaleString(),
      successRate: macroResult.successRate,
    },
    trumpResult: {
      totalToRun: trumpResult.totalToRun.toLocaleString(),
      successCount: trumpResult.successCount.toLocaleString(),
      failCount: trumpResult.failCount.toLocaleString(),
      oldViewCount: trumpResult.oldViewCount.toLocaleString(),
      newViewCount: trumpResult.newViewCount.toLocaleString(),
      successRate: trumpResult.successRate,
    },
    completedAt: now
  }
};

/**
 * Optimized for '深談總經' (200 Requests)
 * Pattern: Chunked Batching (Size 5)
 */

const fetch = require('node-fetch');

// --- Helper: Get a Random UA ---
function getRandomUA() {
  const uas = [
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/131.0.0.0 Safari/537.36',
    'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) Safari/605.1.15',
    'Mozilla/5.0 (iPhone; CPU iPhone OS 17_6 like Mac OS X) Safari/604.1'
  ];
  return uas[Math.floor(Math.random() * uas.length)];
}

// --- Helper: Process Batch ---
async function processBatch(url, size) {
  const tasks = [];
  for (let i = 0; i < size; i++) {
    const ua = getRandomUA(); // Generated exactly when needed
    tasks.push(
      fetch(url, {
        method: 'GET',
        headers: { 'User-Agent': ua },
      })
      .then(res => res.ok)
      .catch(() => false)
    );
  }
  return await Promise.all(tasks);
}

// --- Main Logic ---
async function main() {
  const sourceNode = $('Build URL 深談總經').first().json;
  const targetUrl = sourceNode.url;

  const totalToRun = 200; // Smaller count for this channel
  const chunkSize = 10; 

  const delayMin = 300;        // Randomize delay
  const delayMax = 500;        // Between 200-500ms
  const randomDelay = () => Math.floor(Math.random() * (delayMax - delayMin) + delayMin);

  let successCount = 0;
  let failCount = 0;

  for (let i = 0; i < totalToRun; i += chunkSize) {
    // Determine the size of the current batch (handles the remainder)
    const currentBatchSize = Math.min(chunkSize, totalToRun - i);

    const results = await processBatch(targetUrl, currentBatchSize);
    results.forEach(res => res ? successCount++ : failCount++);

    if (i + chunkSize < totalToRun) {
      await new Promise(res => setTimeout(res, randomDelay()));
    }
  }

  return {
    json: {
      channel: '深談總經',
      title: sourceNode.title,
      totalToRun,
      successCount,
      failCount,
      oldViewCount: sourceNode.viewCount,
      newViewCount: sourceNode.viewCount + successCount,
      successRate: ((successCount / totalToRun) * 100).toFixed(0) + '%'
    }
  };
}

return main();

